definition.script:
pipeline {

    agent{
        label 'nhl2283w_laptop'
    }



    environment {
        USER_NAME = credentials('workshop_credentials_user_name_id')
        PASSWORD = credentials('workshop_credentials_password_id')
    }



    stages{


        stage("Lets see some credentials") {


            steps{
                echo "${USER_NAME}"
                echo "${PASSWORD}"
            }


        }


    }

}
